result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/teelite.py", "content": "#!/usr/bin/env python3
"""teelite.py - mirror stdin to stdout and to each FILE argument.

Usage: teelite.py [-a] [FILE ...]

  -a  append to the given FILEs instead of truncating them

If the downstream consumer of stdout goes away (e.g. `| head`), teelite
notes the BrokenPipeError on stderr, keeps mirroring the remaining input
into the FILEs, and still exits with status 0.
"""

import sys


def main(argv):
    append = False
    paths = []
    for arg in argv:
        if arg == "-a":
            append = True
        elif arg == "--":
            continue
        else:
            paths.append(arg)

    mode = "ab" if append else "wb"
    files = [open(p, mode) for p in paths]

    stdin = sys.stdin.buffer
    stdout = sys.stdout.buffer
    stdout_broken = False

    try:
        while True:
            chunk = stdin.read(65536)
            if not chunk:
                break
            if not stdout_broken:
                try:
                    stdout.write(chunk)
                    stdout.flush()
                except BrokenPipeError:
                    stdout_broken = True
                    print(
                        "teelite: stdout closed by downstream consumer "
                        "(BrokenPipeError); continuing to write files",
                        file=sys.stderr,
                    )
            for f in files:
                f.write(chunk)
                f.flush()
    finally:
        for f in files:
            f.close()
        # Suppress noisy errors when stdout is already gone.
        try:
            stdout.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        # Interpreter-shutdown flush can still hit a dead pipe.
        sys.exit(0)
